import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { getSubjectHandler } from "../handlers/getSubjectHandler";
import type { ApiError } from "../runtime/client";
import type { FactFoldSubjectEntityType } from "../types/FactFoldSubjectEntityType";

type Data = Awaited<ReturnType<typeof getSubjectHandler>>;

export function useGetSubject(
  subjectId: FactFoldSubjectEntityType,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["getSubject", subjectId],
    queryFn: () => getSubjectHandler(subjectId),
    ...options,
  });
}
